pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address newOwnerCandidate, bool callerIsOwner) public {

        address caller = callerIsOwner ? address(this) : address(0xBEEF);

        if (newOwnerCandidate == address(0)) return;

        if (caller == address(this)) {
            bool ok;
            try c.transferOwnership(newOwnerCandidate) {
                ok = true;
            } catch {
                ok = false;
            }

            assertTrue(ok);
        } else {
            vm.prank(caller);
            bool ok;
            try c.transferOwnership(newOwnerCandidate) {
                ok = true;
            } catch {
                ok = false;
            }
            assertTrue(!ok);
        }
    }
}
